:root {
  --ink: #24352d;
  --leaf: #4f7b5b;
  --mint: #dfeee0;
  --cream: #fffdf4;
  --coral: #dd765d;
}

.nest-card {
  width: 360px;
  padding: 18px;
  border: 2px solid var(--leaf);
  border-radius: 18px;
  background: var(--cream);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.bird {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  border-radius: 14px;
  background: var(--mint);
  font-size: 26px;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--leaf);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.2px;
}

h1 {
  margin: 0;
  color: var(--ink);
  font-size: 20px;
  line-height: 1.1;
}

.status {
  margin: 16px 0 12px;
  color: var(--leaf);
  font-size: 14px;
  font-weight: 600;
}

button {
  width: 100%;
  padding: 9px 12px;
  border: 0;
  border-radius: 9px;
  background: var(--coral);
  color: var(--cream);
  font-size: 14px;
  font-weight: 700;
}
